const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Approved Item did not atomically claim a valid content_id. Run from the start and ensure an idea_approved row exists.');
}
if (!title) {
  throw new Error('Fetch Next Approved Item did not produce a title. Re-run from Manual Trigger and inspect the fetch node output.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 45);
if (!Number.isFinite(targetDurationSeconds) || targetDurationSeconds <= 0) {
  throw new Error('target_duration_seconds must be a positive number.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    confidence_label: String($json.confidence_label ?? 'unverified').trim() || 'unverified',
    target_duration_seconds: targetDurationSeconds,
    source_payload_json: $json.source_payload_json ?? {},
    status_after_success: 'script_complete',
    brand_tone: 'cinematic, concise, credible',
    narrator_style: 'calm, serious, engaging',
    ending_signature_family: 'thought-provoking close'
  }
}];

const sourcePayload = $json.source_payload_json ?? {};
const flattenText = (value, keyPath = '') => {
  if (value == null) return [];
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const text = String(value).trim();
    return text ? [keyPath + text] : [];
  }
  if (Array.isArray(value)) {
    return value.flatMap((entry, index) => flattenText(entry, keyPath ? keyPath + (index + 1) + '. ' : ''));
  }
  if (typeof value === 'object') {
    return Object.entries(value).flatMap(([key, entry]) => flattenText(entry, key + ': '));
  }
  return [];
};
const sourceNotesLines = [];
if (Array.isArray(sourcePayload.notes)) {
  sourceNotesLines.push(...sourcePayload.notes.map((entry) => String(entry ?? '').trim()).filter(Boolean));
}
for (const key of ['summary', 'description', 'context', 'source_text']) {
  const text = String(sourcePayload[key] ?? '').trim();
  if (text) sourceNotesLines.push(text);
}
if (sourceNotesLines.length === 0) {
  sourceNotesLines.push(...flattenText(sourcePayload));
}
const sourceNotes = sourceNotesLines.length ? sourceNotesLines.join('\n') : 'No source notes were provided. Keep the script cautious and explicit about uncertainty.';
const confidenceContext = 'Current stored confidence label: ' + $json.confidence_label + '. Preserve or lower certainty unless the source notes clearly support a stronger confidence label.';
const systemPrompt = [
  'You are the script writer for a faceless English-language Instagram Reel channel focused on cinematic true-story, mystery, history, and unexplained-storytelling content.',
  '',
  'Your job is to turn the provided topic and source notes into a short-form Reel script package that is:',
  '',
  '- concise',
  '- spoken, not essay-like',
  '- emotionally engaging',
  '- visually suggestive',
  '- fact-aware',
  '',
  'Hard rules:',
  '',
  '- treat source notes as the factual boundary',
  '- do not invent factual claims that are not supported by the source notes',
  '- if a claim is uncertain or disputed, reflect that in the confidence_label and wording',
  '- optimize the first line for audience retention',
  '- write in plain spoken English',
  '- avoid clickbait phrasing that sounds spammy or cheap',
  '- avoid stage directions',
  '- avoid hashtags inside the narration script',
  '',
  'Runtime target:',
  '',
  '- aim for a Reel voiceover that fits within ' + $json.target_duration_seconds + ' seconds',
  '',
  'Brand voice:',
  '',
  '- tone: ' + $json.brand_tone,
  '- narrator style: ' + $json.narrator_style,
  '- ending signature family: ' + $json.ending_signature_family,
  '',
  'Return only valid JSON matching the provided response schema.'
].join('\n');
const userPrompt = [
  'Create a research-and-script package for this Reel.',
  '',
  'Topic:',
  $json.title,
  '',
  'Category:',
  $json.category,
  '',
  'Confidence context:',
  confidenceContext,
  '',
  'Source notes:',
  sourceNotes,
  '',
  'Required output goals:',
  '',
  '- produce 3 distinct hook options',
  '- choose the strongest hook as selected_hook',
  '- write one primary narration script',
  '- write one shorter backup script',
  '- write one Instagram caption draft',
  '- write one soft CTA line',
  '- write on-screen text lines that align with the narration',
  '',
  'Output requirements:',
  '',
  '- keep the narration concise enough for the target runtime',
  '- make the first 2 sentences strong',
  '- preserve factual caution when certainty is low',
  '- keep the ending memorable',
  '- keep the caption compact and on-brand',
  '',
  'Return only JSON.'
].join('\n');
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    confidence_label: $json.confidence_label,
    status_after_success: $json.status_after_success,
    openai_request: {
      model: String($env.OPENAI_RESEARCH_MODEL || $env.OPENAI_TEXT_MODEL || 'gpt-4o-mini').trim(),
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      response_schema: {
        type: 'object',
        additionalProperties: false,
        required: [
          'confidence_label',
          'hook_option_1',
          'hook_option_2',
          'hook_option_3',
          'selected_hook',
          'narration_script',
          'short_script',
          'caption_draft',
          'cta_line',
          'onscreen_text_json'
        ],
        properties: {
          confidence_label: { type: 'string', enum: ['confirmed', 'likely', 'disputed', 'legend', 'unverified'] },
          hook_option_1: { type: 'string', minLength: 1 },
          hook_option_2: { type: 'string', minLength: 1 },
          hook_option_3: { type: 'string', minLength: 1 },
          selected_hook: { type: 'string', minLength: 1 },
          narration_script: { type: 'string', minLength: 1 },
          short_script: { type: 'string', minLength: 1 },
          caption_draft: { type: 'string', minLength: 1 },
          cta_line: { type: 'string', minLength: 1 },
          onscreen_text_json: {
            type: 'array',
            minItems: 1,
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['scene_number', 'text'],
              properties: {
                scene_number: { type: 'integer', minimum: 1 },
                text: { type: 'string', minLength: 1 }
              }
            }
          }
        }
      }
    }
  }
}];

if (!$json.content_id || !$json.title || !$json.openai_request) {
  throw new Error('Build LLM Request did not provide the expected OpenAI request payload.');
}
const apiKey = String($env.OPENAI_API_KEY || $env.LLL_API_KEY || '').trim();
if (!apiKey) {
  throw new Error('Set OPENAI_API_KEY in the repo-root .env before running wf_research_and_script. For backward compatibility, LLL_API_KEY is also accepted.');
}
const request = $json.openai_request;
if (!request.model) {
  throw new Error('No OpenAI model was configured for the research workflow.');
}
const response = await helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/chat/completions',
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  headers: {
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
  },
  body: {
    model: request.model,
    messages: request.messages,
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'research_script_package',
        schema: request.response_schema,
        strict: true
      }
    }
  }
});
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};
if (!(statusCode >= 200 && statusCode < 300) || body.error) {
  throw new Error('OpenAI research call failed (' + (statusCode || 'no status') + '): ' + (body?.error?.message ?? 'unknown error'));
}
const content = body?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('OpenAI research call returned no message content.');
}
let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('OpenAI research response was not valid JSON: ' + error.message);
}
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success ?? 'script_complete',
    generation_model: String(body.model ?? request.model),
    llm_response: parsed,
    provider_metadata: {
      response_id: body.id ?? null,
      usage: body.usage ?? null,
      finish_reason: body?.choices?.[0]?.finish_reason ?? null
    }
  }
}];

const response = $json.llm_response ?? {};
if (!$json.content_id) {
  throw new Error('Call OpenAI Research Model did not provide content_id to Normalize Script Package.');
}
const requiredTextFields = [
  'confidence_label',
  'hook_option_1',
  'hook_option_2',
  'hook_option_3',
  'selected_hook',
  'narration_script',
  'short_script',
  'caption_draft',
  'cta_line'
];
for (const field of requiredTextFields) {
  if (!String(response[field] ?? '').trim()) {
    throw new Error('Call OpenAI Research Model returned an empty ' + field + '.');
  }
}
if (!Array.isArray(response.onscreen_text_json) || response.onscreen_text_json.length === 0) {
  throw new Error('Call OpenAI Research Model did not produce onscreen_text_json.');
}
const onscreenTextJson = response.onscreen_text_json.map((entry, index) => ({
  scene_number: Number(entry?.scene_number ?? index + 1),
  text: String(entry?.text ?? '').trim()
}));
if (onscreenTextJson.some((entry) => !Number.isInteger(entry.scene_number) || entry.scene_number < 1 || !entry.text)) {
  throw new Error('onscreen_text_json must contain positive scene_number values and non-empty text.');
}
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success,
    confidence_label: String(response.confidence_label).trim(),
    hook_option_1: String(response.hook_option_1).trim(),
    hook_option_2: String(response.hook_option_2).trim(),
    hook_option_3: String(response.hook_option_3).trim(),
    selected_hook: String(response.selected_hook).trim(),
    narration_script: String(response.narration_script).trim(),
    short_script: String(response.short_script).trim(),
    caption_draft: String(response.caption_draft).trim(),
    cta_line: String(response.cta_line).trim(),
    onscreen_text_json: onscreenTextJson,
    generation_model: String($json.generation_model ?? '').trim(),
    raw_response_json: {
      provider: 'openai',
      generation_model: String($json.generation_model ?? '').trim(),
      provider_metadata: $json.provider_metadata ?? {},
      parsed_response: response
    }
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '. Re-run from Manual Trigger and verify earlier nodes are not pinned or stale.');
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    confidence_label_sql: String($json.confidence_label ?? 'unverified').replaceAll("'", "''"),
    hook_option_1_sql: String($json.hook_option_1 ?? '').replaceAll("'", "''"),
    hook_option_2_sql: String($json.hook_option_2 ?? '').replaceAll("'", "''"),
    hook_option_3_sql: String($json.hook_option_3 ?? '').replaceAll("'", "''"),
    selected_hook_sql: String($json.selected_hook ?? '').replaceAll("'", "''"),
    narration_script_sql: String($json.narration_script ?? '').replaceAll("'", "''"),
    short_script_sql: String($json.short_script ?? '').replaceAll("'", "''"),
    caption_draft_sql: String($json.caption_draft ?? '').replaceAll("'", "''"),
    cta_line_sql: String($json.cta_line ?? '').replaceAll("'", "''"),
    onscreen_text_json_sql: JSON.stringify($json.onscreen_text_json ?? []).replaceAll("'", "''"),
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    raw_response_json_sql: JSON.stringify($json.raw_response_json ?? {}).replaceAll("'", "''")
  }
}];
